import LoaderInline from '@jetbrains/ring-ui-built/components/loader-inline/loader-inline'
import Message from '@jetbrains/ring-ui-built/components/message/message'
import {Directions} from '@jetbrains/ring-ui-built/components/popup/popup.consts'
import ordinal from 'ordinal'
import {useEffect, useRef, Suspense} from 'react'
import {graphql} from 'react-relay'

import {useRefetchableLazyLoadQuery} from '../../../hooks/relay/useRefetchableLazyLoadQuery'
import {getBuildLocator} from '../../../rest/locators'
import {getBuildHref} from '../../../routes'
import {getBuildType} from '../../../selectors'
import type {BuildId, BuildTypeId} from '../../../types'
import {truthy} from '../../../utils/guards'
import type {Unsubscribe} from '../../../utils/subscriber'
import {getBuildTypeSuffix, getTopics, subscribeOnOverallEvents} from '../../../utils/subscriber'
import * as SubscriptionEvents from '../../../utils/subscriptionEvents'
import RouterLink from '../RouterLink/RouterLink'

import type {StartedBuildMessageQuery} from './__generated__/StartedBuildMessageQuery.graphql'

import styles from './RunBuild.module.css'

import {useAppDispatch, useAppSelector} from 'src/hooks/react-redux'

type Props = {
  buildTypeId: BuildTypeId
  startedBuildId?: BuildId
  setStartedBuildId?: (buildId?: BuildId) => void
}

const query = graphql`
  query StartedBuildMessageQuery($buildLocator: String!, $skip: Boolean!) {
    build(buildLocator: $buildLocator) @skip(if: $skip) {
      state
      queuePosition
      number
    }
  }
`

function StartedBuildMessage({startedBuildId, buildTypeId}: Props) {
  const dispatch = useAppDispatch()
  const buildTypeInternalId = useAppSelector(state => getBuildType(state, buildTypeId)?.internalId)
  const buildHref = startedBuildId != null ? getBuildHref(startedBuildId, buildTypeId) : null
  const unsubscribe = useRef<Unsubscribe>()
  const [{build}, fetchSingleBuildData] = useRefetchableLazyLoadQuery<StartedBuildMessageQuery>(
    query,
    {
      buildLocator: getBuildLocator(startedBuildId),
      skip: startedBuildId == null,
    },
  )
  const buildState = build?.state ?? 'queued'
  const queuePosition = build?.queuePosition
  const buildNumber = build?.number
  useEffect(() => {
    if (startedBuildId != null) {
      unsubscribe.current = subscribeOnOverallEvents(
        [
          buildState === 'queued' && `events/${SubscriptionEvents.BUILD_QUEUE_ORDER_CHANGED};`,
          ...(buildTypeInternalId != null
            ? getTopics(
                getBuildTypeSuffix(buildTypeInternalId),
                [
                  buildState === 'queued' && SubscriptionEvents.BUILD_STARTED,
                  SubscriptionEvents.BUILD_FINISHED,
                  SubscriptionEvents.BUILD_INTERRUPTED,
                ].filter(truthy),
              )
            : []),
        ].filter(truthy),
        fetchSingleBuildData,
      )
    }
    return unsubscribe.current
  }, [startedBuildId, buildTypeInternalId, dispatch, buildState, fetchSingleBuildData])

  return buildState === 'queued' ? (
    <>
      {'The build is '}
      {queuePosition != null && buildHref != null && (
        <>
          {'at '}
          <RouterLink to={buildHref}>{ordinal(queuePosition)}</RouterLink>
          {' position '}
        </>
      )}
      {'in queue'}
    </>
  ) : (
    <>
      {'The build '}
      {buildHref != null && <RouterLink to={buildHref}>{`#${buildNumber}`}</RouterLink>}
      {` is ${buildState}`}
    </>
  )
}

export default function StartedBuildMessageContainer(props: Props) {
  const {startedBuildId, setStartedBuildId} = props
  const loader = <LoaderInline>{'Adding a build to queue'}</LoaderInline>
  return (
    <Message
      icon={null}
      className={styles.popup}
      tailClassName={styles.popupTail}
      directions={[Directions.BOTTOM_LEFT]}
      key={startedBuildId}
      popupProps={{
        onCloseAttempt: () => setStartedBuildId?.(),
        offset: 12,
      }}
    >
      {startedBuildId != null ? (
        <Suspense fallback={loader}>
          <StartedBuildMessage {...props} />
        </Suspense>
      ) : (
        loader
      )}
    </Message>
  )
}
