import Filters12pxIcon from '@jetbrains/icons/filters-12px.svg'
import FiltersIcon from '@jetbrains/icons/filters.svg'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import ButtonGroup from '@jetbrains/ring-ui-built/components/button-group/button-group'
import Dropdown from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import {
  ControlsHeight,
  ControlsHeightContext,
} from '@jetbrains/ring-ui-built/components/global/controls-height'
import type {ListDataItem} from '@jetbrains/ring-ui-built/components/list/consts'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import type {ReactNode, SyntheticEvent} from 'react'
import {useId, useContext, useCallback, useMemo} from 'react'

import type {BuildId, BuildTypeId} from '../../../types'
import {notNull} from '../../../utils/guards'
import {customRunHint} from '../../packages/Hints/HintItems/Hints.buildOverview'
import {useHint} from '../../packages/Hints/Hints.hooks'
import Popup from '../Popup/Popup.lazy'
import PopupMenu from '../Popup/PopupMenu.lazy'
import Tooltip from '../Tooltip/Tooltip'

import StartedBuildMessage from './StartedBuildMessage'

import styles from './RunBuild.module.css'

type Props = {
  className?: string
  buttonClassName?: string
  splitButtonClassName?: string
  popupClassName?: string
  onClick?: (event: Event | SyntheticEvent) => unknown
  onSplitButtonClick?: ((event: Event | SyntheticEvent) => unknown) | null | undefined
  loader?: boolean
  disabled: boolean
  children: string
  isPrimary?: boolean
  note?: ReactNode
  icon?: boolean
  noPermission?: boolean
  triggerDisabled?: boolean
  isVisible?: boolean
  buildTypeId: BuildTypeId
  startedBuildId?: BuildId | undefined
  setStartedBuildId?: (buildId?: BuildId) => void
}
export function RunBuild({
  className,
  buttonClassName,
  splitButtonClassName,
  popupClassName,
  onClick,
  onSplitButtonClick,
  loader,
  disabled,
  children,
  isPrimary,
  note,
  icon = false,
  noPermission = false,
  triggerDisabled = false,
  isVisible = false,
  buildTypeId,
  startedBuildId,
  setStartedBuildId,
}: Props) {
  useHint(isVisible && !noPermission && customRunHint)
  const hasDisabledReason = noPermission || triggerDisabled
  const classes = classNames(className, styles.buttonGroup, {
    [styles.invisible]: disabled && !icon,
  })

  const onRunFromMenu = useCallback(
    (_: unknown, event: Event | SyntheticEvent) => onClick?.(event),
    [onClick],
  )
  const onRunCustomFromMenu = useCallback(
    (_: unknown, event: Event | SyntheticEvent) => onSplitButtonClick?.(event),
    [onSplitButtonClick],
  )
  const dropdown = useMemo(() => {
    const menuItems: (ListDataItem | null)[] = [
      !disabled
        ? {
            label: children,
            onClick: onRunFromMenu,
          }
        : null,
      !disabled && typeof onSplitButtonClick === 'function'
        ? {
            label: 'Run custom build...',
            onClick: onRunCustomFromMenu,
          }
        : null,
    ]

    return (
      <Dropdown
        anchor={
          <IconButton
            className={classes}
            iconClassName={classNames({
              [styles.disabledIcon]: icon && disabled && hasDisabledReason,
            })}
            icon="run"
            loader={loader}
            disabled={disabled && !hasDisabledReason}
            title={children}
          />
        }
      >
        {hasDisabledReason ? (
          <Popup className={classNames(popupClassName, styles.disabledReasonPopup)}>
            {noPermission
              ? "You don't have enough permissions to\u00a0run this\u00a0build"
              : 'Manual triggering is\u00a0disabled in\u00a0this\u00a0build\u00a0configuration'}
          </Popup>
        ) : (
          <PopupMenu
            className={popupClassName}
            activateFirstItem
            closeOnSelect
            data={menuItems.filter(notNull)}
            hint={note}
          />
        )}
      </Dropdown>
    )
  }, [
    children,
    classes,
    disabled,
    hasDisabledReason,
    icon,
    loader,
    noPermission,
    note,
    onRunCustomFromMenu,
    onRunFromMenu,
    onSplitButtonClick,
    popupClassName,
  ])
  const controlsHeight = useContext(ControlsHeightContext)
  const id = useId()

  return (
    <>
      {icon ? (
        dropdown
      ) : (
        <>
          {!disabled && note}
          <ButtonGroup className={classes} split>
            <Button
              className={buttonClassName}
              onClick={onClick}
              loader={loader}
              disabled={disabled}
              data-test="run-build"
              title={children}
              primary={isPrimary}
            >
              {children}
            </Button>
            {typeof onSplitButtonClick === 'function' && (
              <Tooltip delay={100} title="Run custom build" id={id} className={styles.tooltip}>
                <Button
                  aria-labelledby={id}
                  className={classNames(splitButtonClassName, {
                    [styles.splitButtonPrimary]: isPrimary,
                  })}
                  onClick={onSplitButtonClick}
                  loader={loader}
                  disabled={disabled}
                  primary={isPrimary}
                  inline={false}
                  icon={controlsHeight === ControlsHeight.S ? Filters12pxIcon : FiltersIcon}
                />
              </Tooltip>
            )}
          </ButtonGroup>
        </>
      )}
      {(loader || startedBuildId != null) && (
        <StartedBuildMessage
          buildTypeId={buildTypeId}
          startedBuildId={startedBuildId}
          setStartedBuildId={setStartedBuildId}
        />
      )}
    </>
  )
}
export default RunBuild
